Item.method_code:
// Innovatorオブジェクト生成
var iomInv = aras.IomInnovator;

var result = iomInv.newItem("Method", "h4_CreateRelHistory");
result.setProperty("parentId", itemID);
result.setProperty("parentType", itemTypeName);
result.setProperty("revision_summary", "-");//確認事項
result.setProperty("revision_reason", "-");//改定理由
result = result.apply();

if(result.isError())
{
    aras.AlertError(result.getErrorString());
    return;
}

parent.onRefresh();
